CREATE TABLE migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 2 AND 140), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (org_id uuid REFERENCES organizations ON DELETE CASCADE, wallet text NOT NULL, role text NOT NULL CHECK(role IN ('owner','manager','staff','resolver')), PRIMARY KEY(org_id,wallet));
CREATE TABLE events (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations, title text NOT NULL, description text NOT NULL DEFAULT '', location text NOT NULL, chain_address text UNIQUE, cancel_deadline bigint NOT NULL, cancelled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events, title text NOT NULL, capacity integer NOT NULL CHECK(capacity>0), policy jsonb NOT NULL, terms_hash text NOT NULL, policy_address text UNIQUE, published boolean NOT NULL DEFAULT false, revision integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE registrations (id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES sessions, wallet text NOT NULL, seat_state text NOT NULL CHECK(seat_state IN ('Waitlisted','Offered','Reserved','PaymentPending','Active','Released')), deposit_state text, deposit_address text UNIQUE, permit_expires bigint, permit_last_valid_block_height bigint, reserved_until timestamptz, ticket_hash text UNIQUE, ticket_expires timestamptz, late_cancel boolean NOT NULL DEFAULT false, chain_slot bigint NOT NULL DEFAULT 0, revision integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id,wallet));
CREATE INDEX queue_order ON registrations(session_id,created_at,id) WHERE seat_state='Waitlisted';
CREATE TABLE auth_challenges (id uuid PRIMARY KEY, wallet text NOT NULL, message text NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX challenge_expiry ON auth_challenges(expires_at);
CREATE TABLE auth_sessions (token_hash text PRIMARY KEY, wallet text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE checkins (registration_id uuid PRIMARY KEY REFERENCES registrations, actor text NOT NULL, revision integer NOT NULL DEFAULT 1, corrected boolean NOT NULL DEFAULT false, frozen boolean NOT NULL DEFAULT false, eligible_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE disputes (registration_id uuid PRIMARY KEY REFERENCES registrations, description text NOT NULL CHECK(length(description) BETWEEN 10 AND 4000), decision text CHECK(decision IN ('refund','forfeit')), resolver text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evidence (id uuid PRIMARY KEY, registration_id uuid NOT NULL REFERENCES disputes(registration_id), uploader text NOT NULL, media_type text NOT NULL, size integer NOT NULL CHECK(size BETWEEN 1 AND 2097152), content bytea NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE outbox (id uuid PRIMARY KEY, dedup_key text UNIQUE NOT NULL, kind text NOT NULL, registration_id uuid REFERENCES registrations, payload jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'ready' CHECK(status IN ('ready','leased','submitted','done','failed')), available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_owner uuid, attempts integer NOT NULL DEFAULT 0, error_code text, wire_transaction text, signature text, last_valid_block_height bigint, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX runnable_jobs ON outbox(available_at) WHERE status IN ('ready','leased','submitted');
CREATE TABLE ledger (id uuid PRIMARY KEY, registration_id uuid NOT NULL REFERENCES registrations, signature text UNIQUE NOT NULL, slot bigint NOT NULL, refund numeric(20,0) NOT NULL CHECK(refund>=0), penalty numeric(20,0) NOT NULL CHECK(penalty>=0), finalized_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY, wallet text NOT NULL, operation_id uuid REFERENCES outbox, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(operation_id,wallet));
CREATE TABLE audit_log (id bigserial PRIMARY KEY, org_id uuid REFERENCES organizations, actor text NOT NULL, action text NOT NULL, subject text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
